
/**
 * 墨西哥帅哥游slots
 * 
 */
cc.Class({
    extends: require("LMSlots_Slots_Base"),

    properties: {
       
    },

    Init:function(){
        this._super()

        let self = this
        this.node.parent.parent.getComponent("LMSlots_Puzzle").setCallback((freeInfo, chipGame)=>{
            cc.vv.gameData.SetTotalFree(freeInfo.freeCnt);
            cc.vv.gameData.SetFreeTime(freeInfo.freeCnt);
            cc.vv.gameData.SetSubGameData({awardType:0})
            self.ShowTranstionExit()
        })
    },

    //重写
    RegisterEvent:function(){
        // this._super()
        Global.registerEvent(cc.vv.gameData._EventId.GAME423_SHOW_WHEEL_RESULT,this.OnEventWheelResult,this);
    },


    //重写
    StartMove:function(){
        this._super()
        let man = cc.find("reels/reel1/mask/spine_man",this.node)
        man.active = false
        if(this.bBounusGame){
            let role = cc.find("spine_role",this.node)
            let roleSp = role.getComponent(sp.Skeleton)
            roleSp.setAnimation(0,"chuxian",false)
            roleSp.addAnimation(0,"idle",true)
            this.bBounusGame = null
            Global.SlotsSoundMgr.playEffect('man_in')

            //卷轴回收声音
            Global.SlotsSoundMgr.playEffect('reel_down')
        }
        
        //BGM
        Global.SlotsSoundMgr.playNormalBgm()
        
        //更新游戏内的免费次数
        this.UpdateOtherFreeTime()
    },

    //自己游戏构造bonus数据
    GetBonusData:function(idx){
        let bonusData = this._gameInfo.bonusGame
        if(bonusData){
            if(bonusData.coins){
                for(let i = 0; i < bonusData.coins.length; i++){
                    if(bonusData.coins[i].idx == idx){
                        return {t:"coin",num:bonusData.coins[i].num}
                    }
                }
            }
            
            
            
        }
        

    },

    //获取免费游戏中增加的免费次数
    getBonusAddFree:function () {
        let add = 0
        let bonusData = this._gameInfo.bonusGame
        if(bonusData && bonusData.free){
            for(let i = 0; i < bonusData.free.length; i++){
                add += bonusData.free[i].num
            }
        }
        return add
    },

    SetSlotsResult:function(cards){
        //把结果按卷轴结果整理
        let acRow = cards.length / this._col
        let reelResults = []
        for(let i = 0;i < cards.length; i++){
            let row = Math.floor(i / acRow)
            let col = i % this._col
            //配置中有没有这个元素
            if(this._cfg.symbol[cards[i]]){
                let res = {}
                res.sid = cards[i]
                res.data = this.GetBonusData(i+1)
                if(!reelResults[col]) reelResults[col] = []
                reelResults[col].unshift(res)
            }
            
        }
        for(let j = 0; j < this._reels.length; j++){
            let item = this._reels[j]
            let reelRes = reelResults[j]
            item.SetResult(reelRes)
        }
    },

    //获取行号对应的位置
    getPostionByRow:function(nRow){
        return this._reels[0].GetSymbolPosByRow(nRow)
    },

    //重写：小游戏取的数据不一样
    onMsgSpine:function(msg){
        let self = this
        this._gameInfo = msg
        

        let cards = msg.resultCards
        let bBounusGame = (msg.bonusGame.open > 0)
        if(bBounusGame){
            this._bottomScript.ShowBtnsByState("moveing_1")
            cards = msg.bonusGame.cards
        }
        // else{
        //     this._bottomScript.ShowBtnsByState("moveing_2")
        // }


        //从上往下找头
        let rolePos = self.changeWild(cards)
        

        this.SetSlotsResult(cards)
        this.SetReelStateInfo(cards)

        if(bBounusGame){
            this.bBounusGame = true

            //触发了小游戏
            this.SetStopTime(1000)
            cc.tween(this.node)
            .delay(1.5)
            .call(()=> {
                //框特效
                self.ShowReelEffect()
            })
            .delay(4)
            .call(() => {
                //第一列停止
                self._reels[0].StopMove(0)
            })
            .delay(0.6)
            .call(() => {
                let man = cc.find("reels/reel1/mask/spine_man",self.node)
                man.position = self.getPostionByRow(rolePos)
                man.active = true
                let manSp = man.getChildByName("spine").getComponent(sp.Skeleton)
                manSp.paused = true
                cc.tween(man)
                .to(0.5,{position:self.getPostionByRow(1)})
                .call(() => {
                    manSp.paused = false
                    manSp.setAnimation(0,"idle",true)
                })
                .start()

                //人出去
                let role = cc.find("spine_role",self.node)
                let roleSp = role.getComponent(sp.Skeleton)
                roleSp.setMix("skill01","xiaoshi")
                roleSp.setAnimation(0,"xiaoshi",false)
                Global.SlotsSoundMgr.playEffect('man_in')
            })
            .delay(1)
            .call(() => {
                //扩展列
                Global.SlotsSoundMgr.playEffect('reel_up')
                for (let i = 1; i < 5; i++){
                    self._reels[i].AddCount(2,1.2)
                }
            })
            .delay(2)
            .call(() => {
                //2~5列停止
                for(let i = 1; i < 5; i++){
                    let nIter = self.GetReelStopInter(i)
                    self._reels[i].StopMove(nIter)
                }
            })
            // .delay(2)
            // .call(() => {
                
            // })
            .start()
            
        }

    },

    //变wild:转化头/中/尾巴的显示
    changeWild:function(cards){
        let head = 1
        let mid = 102
        let footer = 103
        let rolePos = 0

        let nWild = 0
        let footer_row = this.GetResutByRowCol(cards,0,0) //尾部
        if(footer_row == 1){
            nWild++
        }
        let mid_row = this.GetResutByRowCol(cards,1,0) //中部
        if(mid_row == 1){
            nWild++
        }
        let head_row = this.GetResutByRowCol(cards,2,0) //头部
        if(head_row == 1){
            nWild++
        }

        //只有一个wild
        if(nWild == 1){
            if(footer_row == 1){
                let sid = this.ChangeRowColToIdx(cards,0,0)
                cards[sid] = head
                rolePos = -1
            }
            if(head_row == 1){
                let sid = this.ChangeRowColToIdx(cards,2,0)
                cards[sid] = footer
                rolePos = 3
            }

        }
        if(nWild == 3){
            let sid0 = this.ChangeRowColToIdx(cards,0,0)
            cards[sid0] = footer

            let sid1 = this.ChangeRowColToIdx(cards,1,0)
            cards[sid1] = mid

            let sid2 = this.ChangeRowColToIdx(cards,2,0)
            cards[sid2] = head

            rolePos = 1
        }
        if(nWild == 2){
            if(head_row == 1 && mid_row == 1){
                let sid2 = this.ChangeRowColToIdx(cards,2,0)
                cards[sid2] = mid

                let sid1 = this.ChangeRowColToIdx(cards,1,0)
                cards[sid1] = footer

                rolePos = 2
            }

            if(footer_row == 1 && mid_row == 1){
                let sid0 = this.ChangeRowColToIdx(cards,0,0)
                cards[sid0] = mid

                let sid1 = this.ChangeRowColToIdx(cards,1,0)
                cards[sid1] = head

                rolePos = 0
            }
        }

        return rolePos

        
    },

    //重写
    OnReelBounsActionBefore:function (colIdx) {
        this._super(colIdx)
        for(let i = 0; i < 5; i++){
            let sys = this._reels[i]._symbols
            for(let j = 0; j < sys.length;j++){
                let item = sys[j]
                item.ShowData()

            }
        }
    },

    //每列停止时间间隔 = 每列的停止间隔 + 每列的回弹时间
    //reelIdx:0开始
    GetReelStopInter:function(reelIdx){
        if(reelIdx > 0 && this.CheckTriggerSubGame()){
            return reelIdx*1.5
        }
        else{
            return this._super(reelIdx)
        }
    },

    //重写：显示bonus中奖
    OnSpinEnd:function(){
        let self = this
        
        //显示中奖路线
        this.ShowWinTrace()
        //显示底部赢钱
        let nWin = cc.vv.gameData.GetGameWin()
        let pEndCall = function(){
            

            if(self.CheckTriggerSubGame()){
                let totalFree = self.getBonusAddFree()
                if(totalFree){
                    //bonus结束后，需要检查是否+免费次数
                    self._bottomScript.ShowBtnsByState("moveing_1")
                    let showExtraCall = function () {
                        //更新免费次数
                        cc.vv.gameData.AddTotalFreeTime(totalFree)

                        self.CanDoNextRound()
                    }
                    let node_pop = cc.find("Canvas/safe_node/node_pop_ui")
                    node_pop.active = true
                    let cmp = node_pop.getComponent("TheMinstrel_Pop")

                    cmp.ShowExtraFree(totalFree,showExtraCall)
                    return
                }
                
            }
            //是否中奖,中奖了就不能开始下一局
            let bHit = self.CheckEnterFreeGame()
            if(bHit){
                //所有按钮状态显示成灰太
                self._bottomScript.ShowBtnsByState("moveing_1")
            }
            else{
                
                //是否退出免费游戏
                self.CheckExitFreeGame()
            }
            
        }
        let nTotal = nWin
        if(cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetTotalFree() != cc.vv.gameData.GetFreeTime()){
            nTotal = cc.vv.gameData.GetGameTotalFreeWin()
        }
        this.ShowBottomWin(nWin,nTotal,true,pEndCall)
        
        //显示Bonus中奖
        if(this.CheckTriggerSubGame()){
            for(let i = 1; i < 5; i++){
                let sys = this._reels[i]._symbols
                for(let j = 0; j < sys.length;j++){
                    let item = sys[j]
                    item.ShowBonus(true)
    
                }
            }
        }
        
    },

    //重写
    CheckTriggerSubGame:function(){
        return this.bBounusGame
    },

    //检查是否触发免费
    CheckEnterFreeGame:function(){
        let res = false
        res = (this._gameInfo.select && this._gameInfo.select == true)
        if(res){
            
            //触发了
            let delayCall = function(){
                let endCall = function(){
                    //显示轮盘界面
                    let node = cc.find("Canvas/safe_node/wheel_node")
                    node.active = true
                }
                this.ShowTranstion(endCall)
            }
            this.scheduleOnce(delayCall,1.5)

            //显示scatter触发免费动画
            let ids = this._gameInfo.freeResult.freeInfo.idxs
            for(let i = 0; i < ids.length; i++){
                let item = this.GetSymbolByIdx(ids[i])
                item.playTriggerAnimation()
            }
            Global.SlotsSoundMgr.playEffect('scatter_trigger')
        }
        return res
    },


    //显示bound游戏的入场效果
    ShowReelEffect:function(){
        let self = this

        //人开始弹琴
        let role = cc.find("spine_role",this.node)
        role.active = true
        let roleSp = role.getComponent(sp.Skeleton)
        roleSp.setAnimation(0,"skill01",true)
        roleSp.addAnimation(0,"skill01",false,3)
        roleSp.addAnimation(0,"idle",false,5)
        Global.SlotsSoundMgr.playEffect("man_stimulate")
        
        let music = cc.find("reels_frame/node_eff/spine_music",this.node)
        music.active = true
        let musicSp = music.getComponent(sp.Skeleton)
        musicSp.setAnimation(0,'animation',false)
        musicSp.setCompleteListener(() => {
            let kuang = cc.find("reels_frame/node_eff/spine_kuang",self.node)
            kuang.active = true
            let kuangSp = kuang.getComponent(sp.Skeleton)
            kuangSp.setAnimation(0,"animation1",false)
            kuangSp.addAnimation(0,"animation2",false)
            kuangSp.addAnimation(0,"animation3",false)
            kuangSp.setStartListener((param) => {
                if(param.name == "animation2"){
                    Global.SlotsSoundMgr.playEffect("nudge")
                }
            })
            musicSp.setCompleteListener(null)
        })
        
        
    },
    
    //转场动画
    async ShowTranstion(pEndCall){
        let role = cc.find("spine_role",this.node)
        role.getComponent(sp.Skeleton).setAnimation(0,"skill01",false)
        role.getComponent(sp.Skeleton).addAnimation(0,"idle",true)

        await cc.vv.gameData.awaitTime(0.5)

        // let self = this
        let tranNode = cc.find("Canvas/safe_node/translate_node")
        tranNode.active = true
        let ani = tranNode.getComponent(sp.Skeleton)
        ani.setAnimation(0,"skill02",false)
        let delayCall = function(){
            if(pEndCall){
                pEndCall()
            }

        }
        this.scheduleOnce(delayCall,0.5)
        Global.SlotsSoundMgr.playEffect('transition')
    },

    ShowTranstionExit:function(){
        let self = this
        let endCall = function(){
            //隐藏wheel
            let node = cc.find("Canvas/safe_node/wheel_node")
            node.active = false
            
            
        
        }
        let delayCall = function(){
            let subData = cc.vv.gameData.GetSubGameData()
            if(subData.awardType == 1){
                let add = subData.num
                let nextCall = function(){
                    self.CanDoNextRound()
                }
                self.ShowBottomWin(add,add,true,nextCall)
                
            }
            else{
                //免费
                self.CanDoNextRound()
                let total = cc.vv.gameData.GetTotalFree()
                let rest = cc.vv.gameData.GetFreeTime()
                if(rest > 0){
                    
                    self._bottomScript.ShowFreeModel(true,total-rest,total)
                    self._ShowGameBg(true)
                }

                Global.SlotsSoundMgr.playBgm('free_bgm')
            }
        }
        this.scheduleOnce(delayCall,1)
        this.ShowTranstion(endCall)
    },


    //列准备停止
    //已经开始给symbol设置结果了，但是还没进入回弹节奏
    OnReelReadyToStop:function(colIdx){
        this._super(colIdx)
        if(colIdx>0){ //第一列不要，只有变长的卷轴需要
            if(this.CheckTriggerSubGame()){
                Global.SlotsSoundMgr.playEffect('reel_anticipation')
            }
        }
        
    },


    OnEventWheelResult:function(data){
        let val = data.detail
        let node_pop = cc.find("Canvas/safe_node/node_pop_ui")
        node_pop.active = true
        let cmp = node_pop.getComponent("TheMinstrel_Pop")
        cmp.ShowWheelResult(val)
    },

    //重写
    ReconnectShow:function(){
        //免费是否选择了
        let bSelect = cc.vv.gameData.IsSelectWheel()
        if(bSelect){
            this._bottomScript.ShowBtnsByState("moveing_1")
            let endCall = function(){
                //显示轮盘界面
                let node = cc.find("Canvas/safe_node/wheel_node")
                node.active = true
            }
            this.ShowTranstion(endCall)
        }
        else{
            let total = cc.vv.gameData.GetTotalFree()
            let rest = cc.vv.gameData.GetFreeTime()
            if(rest > 0){
                this._bottomScript.ShowFreeModel(true,total-rest,total)
                let nTotal = cc.vv.gameData.GetTotalFreeWin()
                this._bottomScript.SetWin(nTotal)

                this.CanDoNextRound()
                this._ShowGameBg(true)
                Global.SlotsSoundMgr.playBgm('free_bgm')
            }
            
        }
    },

    //重写：免费游戏结束
    async CheckExitFreeGame(){
        let self = this

        let total = cc.vv.gameData.GetTotalFree()
        let rest = cc.vv.gameData.GetFreeTime()
        if(total>0 && rest ==0){
            this._bottomScript.ShowBtnsByState("moveing_1")
            await cc.vv.gameData.awaitTime(1.5)
            //结束了，显示免费游戏的总赢钱
            this._ShowFreeBalance()
            Global.SlotsSoundMgr.stopBgm()
        }
        else{
            self.CanDoNextRound()
        }
    },

    //显示免费游戏结算
    _ShowFreeBalance:function(){
        let self = this
        
        let node_balance = cc.find("Canvas/safe_node/node_free_balance")
        node_balance.active = true
        let btnCollect = cc.find("ui_bg/btn_collect",node_balance)
        let freeWin = cc.vv.gameData.GetGameTotalFreeWin()
        let endCall = function(){
            let lbl_coin = cc.find("ui_bg/lbl_coin",node_balance)
            Global.doRoallNumEff(lbl_coin,0,freeWin,1.5,null,null,0,true)
            // Global.SlotsSoundMgr.playEffect('win_rollup')
            
            cc.vv.gameData.checkAutoPlay(btnCollect,self._OnClickFreeBalance.bind(self));
            btnCollect.on('click',self._OnClickFreeBalance,self)
        }
        btnCollect.off('click',self._OnClickFreeBalance,self)
        Global.showAlertAction(cc.find("ui_bg",node_balance),true,0,1,endCall)

        Global.SlotsSoundMgr.playEffect('popup_collect')
    },

    async _OnClickFreeBalance(){
        let self = this
        let node_balance = cc.find("Canvas/safe_node/node_free_balance")
        cc.find("ui_bg/btn_collect",node_balance).stopAllActions();
        let lbl_coin = cc.find("ui_bg/lbl_coin",node_balance)
        if(lbl_coin.getNumberOfRunningActions()>0){
            let freeWin = cc.vv.gameData.GetGameTotalFreeWin()
            lbl_coin.stopAllActions()
            lbl_coin.getComponent(cc.Label).string = Global.FormatNumToComma(freeWin)
            return
        }
        let popbg = cc.find("ui_bg",node_balance)
        if(popbg.getNumberOfRunningActions() > 0){
            cc.log('弹窗动作还没执行玩，还不能执行关闭弹窗！')
            return
        }
        let winoutCall = function(){
            node_balance.active = false
            let endCall = function(){
                //显示轮盘界面
                self._ShowGameBg(false)
                self._bottomScript.ShowFreeModel(false)
                
                
            }
            self.ShowTranstion(endCall)
        }
        await Global.SlotsSoundMgr.playEffectByUnSync('popup_out')
        Global.showAlertAction(popbg,false,0,1,winoutCall)
        
        await cc.vv.gameData.awaitTime(2)
        //加上免费的赢钱
        
        let freeWin = cc.vv.gameData.GetGameTotalFreeWin()
        await self.ShowBottomWin(freeWin,freeWin,true,null,1)
        self.CanDoNextRound()
        
        
    },

    _ShowGameBg:function(bFree){
        let normalBg = cc.find("Canvas/safe_node/spr_bg_normal")
        let normalFree = cc.find("Canvas/safe_node/spr_bg_free")
        normalBg.active = !bFree
        normalFree.active = bFree

        let freeTimeNode = cc.find('Canvas/safe_node/slots/free_time')
        freeTimeNode.active = bFree
        this.UpdateOtherFreeTime()

        // let logo = cc.find('Canvas/safe_node/logo_txt')
        // logo.active = !bFree

        //替换卷轴背景
        let bgpath = 'Canvas/safe_node/slots/reels_bg/reel_bg'
        // let topFrame = 'Canvas/safe_node/slots/reels_frame/reel%s/frame1'
        let baseAtlas = cc.vv.gameData.GetAtlasByName('base')
        let bgSprite = baseAtlas.getSpriteFrame('reel_04')
        // let topSprite = baseAtlas.getSpriteFrame('theme135_reel_frame6')
        if(bFree){
            bgSprite = baseAtlas.getSpriteFrame('reel_05')
            // topSprite = baseAtlas.getSpriteFrame('theme135_reel_frame7')
        }
        for(let i = 0; i < 5; i++){
            let node = cc.find(bgpath + (i+1))
            if(node){
                node.getComponent(cc.Sprite).spriteFrame = bgSprite
            }
            // if(i > 0){
            //     let frameNode = cc.find(cc.js.formatStr(topFrame,i+1))
            //     frameNode.getComponent(cc.Sprite).spriteFrame = topSprite
            // }
        }


    },

    //自己游戏内部还有一个免费次数的显示
    UpdateOtherFreeTime:function(){
        let freeTimeNode = cc.find('Canvas/safe_node/slots/free_time')
        let nTotal = cc.vv.gameData.GetTotalFree()
        let reset = cc.vv.gameData.GetFreeTime()
        if(nTotal>0){
            let lblTotal = cc.find('lbl_total',freeTimeNode)
            lblTotal.getComponent(cc.Label).string = nTotal
            let lblUsed = cc.find('lbl_used',freeTimeNode)
            lblUsed.getComponent(cc.Label).string = nTotal - reset
        }
    }
});
