/**
 * 弹窗管理
 */
cc.Class({
    extends: require("LMSlots_PauseUI_Base"),

    properties: {
        _showNode:null,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad () {
        let btnCollect = cc.find("pop_wheel_result/node_coin/btn_collect",this.node)
        Global.btnClickEvent(btnCollect,this.OnClickCollect,this)
        let btnStart = cc.find("pop_wheel_result/node_freegames/btn_start",this.node)
        Global.btnClickEvent(btnStart,this.OnClickStart,this)
    },

    start () {

    },

    //显示wheel结果
    ShowWheelResult:function(data){
        this._WheelResultData = data

        Global.SlotsSoundMgr.playEffect('pupup_in1')

        if(this._showNode) this._showNode.active = false
        let node_result = cc.find("pop_wheel_result",this.node)
        node_result.active = true
        this._showNode = node_result

        let node_coin = cc.find("node_coin",node_result)
        node_coin.active = data.awardType == 1
        let node_free = cc.find("node_freegames",node_result)
        node_free.active = !node_coin.active
        if(data.awardType == 1){
            let self = this;
            Global.showAlertAction(node_result,true,null,null,function () {
                let btnCollect = cc.find("btn_collect",node_coin);
                btnCollect.getComponent(cc.Button).interactable = true;
                cc.vv.gameData.checkAutoPlay(btnCollect, self.OnClickCollect.bind(self));
            })
            //金币
            let lbl_coin = cc.find("lbl_coin",node_coin)
            // lbl_coin.getComponent(cc.Label).string = Global.FormatNumToComma(data.num)

            Global.doRoallNumEff(lbl_coin,0,data.num,3,null,null,0,true)
            Global.SlotsSoundMgr.playEffect('win_rollup')

            let majorType = [1,5,9,13]
            for(let i = 0; i < majorType.length; i++){
                let nodeMajor = cc.find("res_"+majorType[i],node_coin)
                nodeMajor.active = majorType[i] == data.idx
            }
        }
        else{
            let self = this;
            Global.showAlertAction(node_result,true,null,null,function () {
                let btnStart = cc.find("btn_start",node_free);
                btnStart.getComponent(cc.Button).interactable = true;
                cc.vv.gameData.checkAutoPlay(btnStart,self.OnClickStart.bind(self));
            })
            //免费
            let lbl_time = cc.find("lbl_time",node_free)
            lbl_time.getComponent(cc.Label).string = Global.FormatNumToComma(data.num)

            cc.vv.gameData.SetFreeTime(data.num)
            cc.vv.gameData.SetTotalFree(data.num)
        }

        //设置背景图
        let hitIdx = data.num
        let tarSp = "theme135_popup_bg7"
        if(hitIdx == 5){
            tarSp = "theme135_popup_bg1"
        }
        else if(hitIdx == 8){
            tarSp = "theme135_popup_bg3"
        }
        else if(hitIdx == 20){
            tarSp = "theme135_popup_bg6"
        }
        else if(hitIdx == 15){
            tarSp = "theme135_popup_bg5"
        }
        else if(hitIdx == 10){
            tarSp = "theme135_popup_bg4"
        }
        else if(hitIdx == 7){
            tarSp = "theme135_popup_bg2"
        }

        let spr_bg = cc.find("spr_bg",node_result)
        let atlas = cc.vv.gameData.GetAtlasByName("popup")
        spr_bg.getComponent(cc.Sprite).spriteFrame = atlas.getSpriteFrame(tarSp)
    },

    async ShowExtraFree(nTime,nextCall){
        let self = this

        Global.SlotsSoundMgr.playEffect('pupup_in1')

        if(this._showNode) this._showNode.active = false
        let node_extra = cc.find("node_extra_free",this.node)
        this._showNode = node_extra
        node_extra.active = true
        let lbl_time = cc.find("lbl_time",node_extra)
        lbl_time.getComponent(cc.Label).string = nTime
        let sprTime1 = cc.find("txt_frees1",node_extra)
        sprTime1.active = nTime == 1
        let sprTime2 = cc.find("txt_frees2",node_extra)
        sprTime2.active = !sprTime1.active

        Global.showAlertAction(node_extra,true)

        await cc.vv.gameData.awaitTime(2)

        await Global.SlotsSoundMgr.playEffectByUnSync('popup_out')
        let closeEndCall = function (params) {
            if(nextCall){
                nextCall()
            }
            self.HidePopNode()
        }
        Global.showAlertAction(node_extra,false,null,null,closeEndCall)

        // let delayCall = function () {
            
        // }
        // this.scheduleOnce(delayCall,2)
    },


    HidePopNode:function(){
        this.node.active = false
    },

    //收集
    async OnClickCollect(){
        let self = this
        let btnCollect = cc.find("pop_wheel_result/node_coin/btn_collect",this.node)
        btnCollect.getComponent(cc.Button).interactable = false;
        btnCollect.stopAllActions();

        let lbl_coin = cc.find("pop_wheel_result/node_coin/lbl_coin",this.node)
        if(lbl_coin.getNumberOfRunningActions() > 0){
            lbl_coin.stopAllActions()
            lbl_coin.getComponent(cc.Label).string = Global.FormatNumToComma(self._WheelResultData.num)
            await cc.vv.gameData.awaitTime(0.2)
        }

        
        let node_result = cc.find("pop_wheel_result",this.node)
        if(node_result.getNumberOfRunningActions() == 0){
            let closeEndCall = function(){
                self.HidePopNode()
                let slotScp = cc.vv.gameData.GetSlotsScript()
                slotScp.ShowTranstionExit()
            }
            await Global.SlotsSoundMgr.playEffectByUnSync('popup_out')
            Global.showAlertAction(node_result,false,null,null,closeEndCall)
        }

    },

    //开始免费
    async OnClickStart(){
        let self = this
        let btnStart = cc.find("pop_wheel_result/node_freegames/btn_start",this.node)
        btnStart.getComponent(cc.Button).interactable = false;
        btnStart.stopAllActions();
        let node_result = cc.find("pop_wheel_result",this.node)
        if(node_result.getNumberOfRunningActions() == 0){
            let closeEndCall = function(){
                self.HidePopNode()
                let slotScp = cc.vv.gameData.GetSlotsScript()
                slotScp.ShowTranstionExit(true)
    
            }
            await Global.SlotsSoundMgr.playEffectByUnSync('popup_out')
            Global.showAlertAction(node_result,false,null,null,closeEndCall)
        }
        
        

        
    }

    // update (dt) {},
});
