/**
 * 墨西哥帅哥卷轴
 */
cc.Class({
    extends: require("LMSlots_Reel_Base"),

    properties: {
        
    },

    //重写：自己控制卷轴回收
    StartMove:function(){
        this.StartRecycleSymbol()
        this._super()
        
    },

    /**重写：和加速没关联的图标如果播放停止动画，就需要自己播放 */
    playReelStop() {
        this._super()

        if(this.isInBonusGame()){
            let bPlayCoin = false
            for(let i = 0; i < this._originResult.length; i++){
                let item = this._symbols[i]
                item.playStopAnimation()
                let id = item.GetShowId()
                if( id == 15 || id == 14 || id == 13 || id == 12 || id == 11){
                    bPlayCoin = true
                }
            }
            if(bPlayCoin){
                Global.SlotsSoundMgr.playEffect('symbol_coin')
            }
        }
        
    },

    isInBonusGame:function () {
        let slot = cc.vv.gameData.GetSlotsScript()
        if(slot){
            return slot.CheckTriggerSubGame()
        }
    },

    //变卷轴开始
    AddCount:function(count,deltaTime=0.5,offsetY=0){
        this._super(count,deltaTime,offsetY)
        if(this.isInBonusGame() && count > 0){
            for(let i = 0; i < this._symbols.length; i++){
                let item = this._symbols[i]
                item.ShowMask(true)
            }
        }
    },

    //高度变化通知
    //如果自己还有需要根据卷轴变化来处理逻辑
    OnReelHeigtChange:function(nAddHeight){
        this._super(nAddHeight)

        //改变高度.这里只相应一列的。不然4列都加就不对了
        if(this._reelIdx == 2){
            let freeTimeNode = cc.find('Canvas/safe_node/slots/free_time')
            freeTimeNode.y += nAddHeight
        }
        
    },

    
    
});
