
/**墨西哥帅哥轮盘
 * 
*/
cc.Class({
    extends: require("LMSlots_PauseUI_Base"),

    properties: {
        
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad () {
        this._GRAND = 888
        this._MAJOR = 777
        this._MINOR = 666
        this._MINI = 555

        //轮盘配置
        this._ReelConfig = [this._GRAND,5,8,20,this._MAJOR,5,10,7,this._MINOR,5,8,20,this._MINI,15,10,7]

        cc.vv.NetManager.registerMsg(MsgId.SLOT_SUBGAME_DATA, this.OnRecvMsgSubAction, this);

        this._startBtn = cc.find("btn_start",this.node)
        Global.btnClickEvent( this._startBtn,this.OnClickStart,this)

        
    },

    onDestroy(){
        cc.vv.NetManager.unregisterMsg(MsgId.SLOT_SUBGAME_DATA, this.OnRecvMsgSubAction, false,this);
    },

    onEnable(){
        this.InitShow()
    },

    onDisable(){
        this.ShowLogoTxt(true)
        Global.dispatchEvent(cc.vv.gameData._EventId.SLOT_SHOW_HEADFOOTER_MASK,false)
        
    },

    start () {

        
    },

    InitShow:function(){
        this._isStart = null
        this.ShowLogoTxt(false)
        Global.dispatchEvent(cc.vv.gameData._EventId.SLOT_SHOW_HEADFOOTER_MASK,true)

        let nodeWheel = cc.find("wheel_pan",this.node)
        nodeWheel.angle = 0
        this.ShowResultAni(false)
        this.ShowIdle(true)
        let idleSpin  = cc.find("btn_spine",this.node)
        let idleSp = idleSpin.getComponent(sp.Skeleton)
        idleSp.setAnimation(0,"animation1",true)

        Global.SlotsSoundMgr.playBgm('wheel_bgm')

        this.CheckPrizePoolLock()

        cc.vv.gameData.checkAutoPlay( this._startBtn,this.OnClickStart.bind(this));
    },

    //检查奖池是否解锁
    CheckPrizePoolLock:function(){
        let bGrandLock = cc.vv.gameData.IsPrizePoolLock(3)
        let nodeGrandLock = cc.find('wheel_pan/grand_lock',this.node)
        nodeGrandLock.active = bGrandLock


        let bMajorLock = cc.vv.gameData.IsPrizePoolLock(2)
        let nodeMajorLock = cc.find('wheel_pan/major_lock',this.node)
        nodeMajorLock.active = bMajorLock

        let bMinorLock = cc.vv.gameData.IsPrizePoolLock(1)
        let nodeMinorLock = cc.find('wheel_pan/minor_lock',this.node)
        nodeMinorLock.active = bMinorLock

        let bMiniLock = cc.vv.gameData.IsPrizePoolLock(0)
        let nodeMiniLock = cc.find('wheel_pan/mini_lock',this.node)
        nodeMiniLock.active = bMiniLock
    },

    ShowResultAni:function(bShow){
        let node = cc.find("wheel_win_spine",this.node)
        node.active = bShow
    },

    ShowIdle:function(bShow){
        let nodepanAni = cc.find("wheel_pan/wheel_idle_spine",this.node)
        nodepanAni.active = bShow
        let nodePointAni = cc.find("wheel_pointer/pointer_spine",this.node)
        nodePointAni.active = bShow
        
    },

    //点击开始
    OnClickStart:function(){
        let self = this
        if(this._isStart) return
        this._isStart = true
        this._startBtn.stopAllActions();

        let req = {c: MsgId.SLOT_SUBGAME_DATA};
        req.gameid = cc.vv.gameData.getGameId()
        req.data = {}
        req.data.rtype = 1

        cc.vv.NetManager.send(req,true);

        Global.SlotsSoundMgr.playEffect("wheel_press")

    },

    OnRecvMsgSubAction:function(msg){
        let self=this
        if(msg.code == 200 && msg.data.rtype == 1){
            this._subData = msg.data
            cc.vv.gameData.SetSubGameData(this._subData)


            this.ShowIdle(false)
            let idleSpin  = cc.find("btn_spine",this.node)
            let idleSp = idleSpin.getComponent(sp.Skeleton)
            idleSp.setAnimation(0,"animation2",false)
            
            let delayCall = function(){
                // self._subData = {idx:6,awardType:2,num:7}
                // cc.vv.gameData.SetSubGameData(self._subData)

                Global.SlotsSoundMgr.playEffect("wheel_spin")
                self.ShowWheelTurn(self._subData)
            }
            this.scheduleOnce(delayCall,1)
        }
    },

    //轮盘旋转
    ShowWheelTurn:function(data,callback){
        let self = this
        let idx = data.idx
        let nodeWheel = cc.find("wheel_pan",this.node)
        let rot = 8*360 + (16-(idx - 1))*(360/this._ReelConfig.length)
        cc.tween(nodeWheel)
        .to(6.5,{angle:-rot},{easing:"quadInOut"})
        .call(() => {
            //停下，显示结果
            self.ShowResultAni(true)
            Global.SlotsSoundMgr.playEffect("wheel_win")
            Global.SlotsSoundMgr.stopBgm()
        })
        .delay(2)
        .call(() => {
            //弹出提示
            Global.dispatchEvent(cc.vv.gameData._EventId.GAME423_SHOW_WHEEL_RESULT,this._subData)
            if(callback){
                callback()
            }
        })
        .start()
    },

    ShowLogoTxt(bShow){
        let logo = cc.find('Canvas/safe_node/logo_txt')
        logo.active = bShow
    }

    // update (dt) {},
});
