/**
 * 墨西哥帅哥，奖池
 */

cc.Class({
    extends: require("LMSlots_PrizePool_Base"),

    properties: {
        
    },

    
    //各个节点上的解锁/锁定表现
    ShowNodeLockByNode:function(node,bLock,unLockBet,poolType,bInit){
        let targetJpNode = node
        if(targetJpNode){
            let aniType = [3,3,2,1] //对应奖池的动画前缀类型
            let lock_node = targetJpNode.getChildByName('jp_lock')
            if(lock_node){
                let jp_title = targetJpNode.getChildByName('spr_title')
                lock_node.active = true
                let un_lock_bet = lock_node.getChildByName('un_lock_bet')
                un_lock_bet.getComponent(cc.Label).string = Global.convertNumToShort(unLockBet)

                let lockSp = lock_node.getComponent(sp.Skeleton)
                if(bLock){
                    let delayCall = function(){
                        if(jp_title){
                            jp_title.color = cc.Color.GRAY
                        }
                        un_lock_bet.active = true
                    }
                    if(bInit){
                        
                        delayCall()
                        //锁
                        lockSp.setAnimation(0,cc.js.formatStr("animation%s_%s",aniType[poolType],2),true)
                    }
                    else{
                        
                        this.scheduleOnce(delayCall,0.6)
                        //锁
                        lockSp.setAnimation(0,cc.js.formatStr("animation%s_%s",aniType[poolType],1),false)
                        lockSp.addAnimation(0,cc.js.formatStr("animation%s_%s",aniType[poolType],2),true)
                        Global.SlotsSoundMgr.playEffect('lock')
                    }
                    
                }
                else{
                    let delayCall = function(){
                        un_lock_bet.active = false
                        if(jp_title){
                            jp_title.color = cc.Color.WHITE
                        }
                    }

                    if(bInit){
                        delayCall()
                        lockSp.setAnimation(0,cc.js.formatStr("animation%s_%s",aniType[poolType],3),false)
                    }
                    else{
                        
                        this.scheduleOnce(delayCall,0.6)
                        lockSp.setAnimation(0,cc.js.formatStr("animation%s_%s",aniType[poolType],3),false)
                        Global.SlotsSoundMgr.playEffect('unlock')
                    }
                    
                }
                
            }
            
        }
    }
    // update (dt) {},
});
