/**墨西哥帅哥-符号表 
 * 
*/
cc.Class({
    extends: require("LMSlots_Symbol_Base"),

    properties: {
        
    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    start () {

    },

    //重写
    StartMove:function(){
        this._super()
        this.SetText()
        this.ShowMask(false)
        
    },

    //显示bonus中奖
    ShowBonus:function(bShow){
        if(this._data){
            if(bShow){
                this.SetText(this._data.num)
                if(this.isInBonusGame()){
                    
                    this.playWinAnimation()
                }
                
            }
            else{
                this.SetText()
            }
        }
    },

    //
    ShowData:function () {
        if(this._data){
            this.SetText(this._data.num)
        }
    },

    //开始回弹
    isCanShowBonus:function () {
        let res = false
        if(this._id > 10 && this._id < 19){
            res = true
        }
        return res
    },

    //显示蒙板
    ShowMask:function(bShow){
        let mask = cc.find("mask",this.node)
        mask.active = bShow
    },

    SetText:function(num){
        let bCanShow = false
        if(this._id == 15 || this._id == 16 || this._id == 17 || this._id == 18){
            bCanShow = true
        }

        let txt = cc.find("coin_num",this.node)
        if(num && bCanShow){
            txt.active = true
            txt.getComponent(cc.Label).string = Global.formatNumShort(num, 1)
        }
        else{
            txt.active = false
            // this._data = null
        }
        
    },



    isInBonusGame:function () {
        let slot = cc.vv.gameData.GetSlotsScript()
        if(slot){
            return slot.CheckTriggerSubGame()
        }
    },

    ShowMask:function(bShow){
        let nodeMask = cc.find('mask',this.node)
        nodeMask.active = bShow
    }

    // update (dt) {},
});
